import json, sys, os, re
run = sys.argv[1]
def norm_file(f): return f.replace("\\","/").lstrip("./")
def norm_title(t): return re.sub(r"\s+"," ",t.strip().lower())
def key(r,f): return (r, norm_file(f["file"]), str(f["line"]), norm_title(f["title"]))
src = {}
for rv in ["correctness","testing","maintainability","reliability","adversarial"]:
    p = os.path.join(run, rv+".json")
    try:
        art = json.load(open(p))
    except Exception as e:
        print("artifact unreadable", rv, e); continue
    for f in art.get("findings", []):
        src[key(art.get("reviewer", rv), f)] = {"why_it_matters": f.get("why_it_matters"), "evidence": f.get("evidence")}
raw = json.load(open(os.path.join(run,"raw-returns.json")))
attached = 0
for ret in raw:
    for f in ret.get("findings", []):
        k = key(ret["reviewer"], f)
        if k in src and src[k]["evidence"]:
            f["evidence"] = src[k]["evidence"]; attached += 1
        else:
            print("NO MATCH", k)
json.dump(raw, open(os.path.join(run,"helper-input.json"),"w"), indent=1, ensure_ascii=False)
print("source-map entries", len(src), "attached", attached)
EOF
